#!/bin/sh
# Verified private fill, retaining previous collections for rollback.
# Input: SHA256(SHA256SUMS), volume root. Package already unpacked in .nieuw.
set -eu
exec python3 - "$@" <<'PYFILL'
import hashlib
import os
import re
import sys
import tempfile
from pathlib import Path


def fatal(message):
    print('vul-kennis-prive: FATAL: ' + message, file=sys.stderr)
    raise SystemExit(1)

want = sys.argv[1] if len(sys.argv) > 1 else ''
if not re.fullmatch('[0-9a-f]{64}', want):
    fatal('first argument must be the 64-hex sha256 of SHA256SUMS')
volume = Path(sys.argv[2] if len(sys.argv) > 2 else '/vul').resolve()
new = volume / '.nieuw'
if not new.is_dir() or new.is_symlink():
    fatal('new package missing')
manifest = new / 'SHA256SUMS'
if not manifest.is_file() or manifest.is_symlink():
    fatal('SHA256SUMS missing in the package')
if hashlib.sha256(manifest.read_bytes()).hexdigest() != want:
    fatal('wrong or altered package')
listed = set()
for line in manifest.read_text().splitlines():
    match = re.fullmatch(r'([0-9a-f]{64})  ([a-zA-Z0-9_./-]+)', line)
    if not match:
        fatal('invalid manifest entry')
    digest, relative = match.groups()
    path = Path(relative)
    if path.is_absolute() or any(part in ('.', '..') or part.startswith('.') for part in relative.split('/')):
        fatal('invalid manifest path')
    if relative in listed:
        fatal('duplicate manifest entry')
    listed.add(relative)
    source = new / relative
    if not source.is_file() or source.is_symlink():
        fatal('file check failed')
    if hashlib.sha256(source.read_bytes()).hexdigest() != digest:
        fatal('file check failed')
files = set()
for source in new.rglob('*'):
    if source.is_symlink() or not (source.is_dir() or source.is_file()):
        fatal('unsafe package entry')
    if source.is_file() and source != manifest:
        files.add(str(source.relative_to(new)))
if files != listed:
    fatal('unlisted files')
collections = sorted(source.name for source in new.iterdir() if source.is_dir())
if not collections:
    fatal('no collection directory in the package')
for name in collections:
    if not re.fullmatch('[a-z0-9][a-z0-9-]*', name):
        fatal('bad collection name')
    target = volume / name
    if target.is_symlink() or (target.exists() and not target.is_dir()):
        fatal('unsafe existing collection')
# A checked package is preserved together with all prior collection directories.
retired = Path(tempfile.mkdtemp(prefix='.retired-', dir=volume))
changed = []
try:
    for name in collections:
        target = volume / name
        old = retired / name
        if target.exists():
            target.rename(old)
        changed.append((name, old.exists()))
        (new / name).rename(target)
    new.rename(retired / 'package')
except OSError:
    for name, had_old in reversed(changed):
        target = volume / name
        if target.exists():
            target.rename(retired / ('failed-' + name))
        if had_old:
            (retired / name).rename(target)
    fatal('fill failed; previous collections restored')
for name in collections:
    count = sum(1 for p in (volume / name).rglob('*.md') if p.is_file())
    print(f'vul-kennis-prive: {name}: {count} files')
print(f'vul-kennis-prive: done ({len(collections)} collection(s))')
PYFILL
